//! MESH parity (Item 4c, 2026-11-21): Rust columns_mesh
//! solver against the Python columns_mesh.mesh_tower solver on
//! the cases of python/test_mesh.py (gates 1, 2, 4 and 5 on the
//! pentane/hexane/heptane column at 150000 Pa, and gate 3's
//! binary column at 101325 Pa at Murphree efficiency E = 1 and
//! E = 0.7, where E is dimensionless).
//!
//! Reference values were generated by running the Python solver
//! on those cases on 2026-11-21 (script recorded in the task
//! report; outputs: stage temperatures T in kelvin (K), stage
//! liquid compositions x (mole fractions, dimensionless), liquid
//! rates L and vapour rates V in mol/s, bottoms rate B in mol/s,
//! reboiler duty Q_reb and condenser duty Q_cond in watts (W),
//! condenser temperature in K). They are not hand-derived.
//!
//! Tolerances (stated): the Rust solver replaces scipy
//! least_squares with the crate Levenberg-Marquardt solver, so
//! agreement is asserted at 1e-6 absolute on compositions,
//! 2e-3 K absolute on temperatures, 1e-3 mol/s absolute on
//! flows, and 1e-4 relative on duties -- looser than the
//! Python battery's own residual gates, tighter than the
//! Python gate-1 CMO-equivalence tolerance of 2e-3 mole
//! fraction. Internal closure is asserted at the Python
//! battery's gates: material residual below 1e-3 mol/s,
//! summation residual below 1e-4, enthalpy residual below 5 W.

use ccr::columns::RaoultThermo;
use ccr::columns_mesh::{mesh_tower, MeshResult};

fn alkane_psat() -> Vec<Box<dyn Fn(f64) -> f64>> {
    let abc = [(14.2706, 2730.9, -26.806), (14.3314, 3004.3, -33.111),
               (14.3748, 3237.52, -40.249)];
    let mut psat: Vec<Box<dyn Fn(f64) -> f64>> = Vec::new();
    for (a, b, c) in abc {
        psat.push(Box::new(move |t: f64| 1000.0 * (a - b / (t + c)).exp()));
    }
    psat
}

fn thermo_cmo() -> RaoultThermo {
    // Gate 1/4/5 thermo of test_mesh.py: pure liquid enthalpy
    // c_i in J/mol constant, pure vapour enthalpy c_i + 28000.
    let cpure = [0.0, 5000.0, 10000.0];
    let hl: Vec<Box<dyn Fn(f64) -> f64>> = cpure.iter()
        .map(|&c| Box::new(move |_t: f64| c) as Box<dyn Fn(f64) -> f64>).collect();
    let hv: Vec<Box<dyn Fn(f64) -> f64>> = cpure.iter()
        .map(|&c| Box::new(move |_t: f64| c + 28000.0) as Box<dyn Fn(f64) -> f64>).collect();
    RaoultThermo { psat: alkane_psat(), hl, hv }
}

fn thermo_tdep() -> RaoultThermo {
    // Gate 2 thermo of test_mesh.py.
    let hl: Vec<Box<dyn Fn(f64) -> f64>> = (0..3)
        .map(|_| Box::new(|t: f64| 150.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>)
        .collect();
    let hv: Vec<Box<dyn Fn(f64) -> f64>> = (0..3)
        .map(|_| Box::new(|t: f64| 30000.0 + 100.0 * (t - 300.0)) as Box<dyn Fn(f64) -> f64>)
        .collect();
    RaoultThermo { psat: alkane_psat(), hl, hv }
}

fn thermo_bin() -> RaoultThermo {
    // Gate 3 binary thermo of test_mesh.py: Clausius-Clapeyron
    // vapour pressures anchored at boiling points 340 K / 380 K
    // at 101325 Pa, constant pure enthalpies in J/mol.
    let mk = |tb: f64| -> Box<dyn Fn(f64) -> f64> {
        Box::new(move |t: f64| 101325.0 * (-30000.0 / 8.314 * (1.0 / t - 1.0 / tb)).exp())
    };
    RaoultThermo {
        psat: vec![mk(340.0), mk(380.0)],
        hl: vec![Box::new(|_t: f64| 0.0), Box::new(|_t: f64| 8000.0)],
        hv: vec![Box::new(|_t: f64| 28000.0), Box::new(|_t: f64| 36000.0)],
    }
}

struct Ref {
    t: &'static [f64],
    x: &'static [&'static [f64]],
    l: &'static [f64],
    v: &'static [f64],
    b: f64,
    qr: f64,
    qc: f64,
    tcond: f64,
}

fn check(name: &str, r: &MeshResult, rf: &Ref) {
    let mut dt = 0.0f64;
    let mut dx = 0.0f64;
    let mut dl = 0.0f64;
    for j in 0..rf.t.len() {
        dt = dt.max((r.t[j] - rf.t[j]).abs());
        dl = dl.max((r.l[j] - rf.l[j]).abs()).max((r.v[j] - rf.v[j]).abs());
        for i in 0..rf.x[j].len() {
            dx = dx.max((r.x[j][i] - rf.x[j][i]).abs());
        }
    }
    println!("{name}: max dT={dt:.3e} K, max dx={dx:.3e}, max dflow={dl:.3e} mol/s,               B={} (ref {}), Qr={} (ref {}), Qc={} (ref {}),               maxmat={:.3e} mol/s, maxenth={:.3e} W, maxsum={:.3e}, overall={:.3e} mol/s",
             r.b, rf.b, r.q_reboiler, rf.qr, r.q_condenser, rf.qc,
             r.max_material_residual_mol_s, r.max_enthalpy_residual_w,
             r.max_summation_residual, r.overall_balance_residual_mol_s);
    assert!(dt < 2e-3, "{name} dT {dt}");
    assert!(dx < 1e-6, "{name} dx {dx}");
    assert!(dl < 1e-3, "{name} dflow {dl}");
    assert!((r.b - rf.b).abs() < 1e-3, "{name} B {}", r.b);
    assert!((r.q_reboiler - rf.qr).abs() < 1e-4 * rf.qr.abs(), "{name} Qr {}", r.q_reboiler);
    assert!((r.q_condenser - rf.qc).abs() < 1e-4 * rf.qc.abs(), "{name} Qc {}", r.q_condenser);
    assert!((r.t_condenser - rf.tcond).abs() < 2e-3, "{name} Tcond {}", r.t_condenser);
    assert!(r.max_material_residual_mol_s < 1e-3, "{name} mat {}", r.max_material_residual_mol_s);
    assert!(r.max_summation_residual < 1e-4, "{name} sum {}", r.max_summation_residual);
    assert!(r.max_enthalpy_residual_w < 5.0, "{name} enth {}", r.max_enthalpy_residual_w);
    assert!(r.overall_balance_residual_mol_s.abs() < 1e-3, "{name} overall {}", r.overall_balance_residual_mol_s);
}

