#[test]
fn mesh_gate1_cmo_limit_parity() {
    let th = thermo_cmo();
    let r = mesh_tower(&[0.4, 0.3, 0.3], 10.0, 12, 6, 4.0, 5.0, &th, 150e3,
                       None, &[1.0], &[], &[], &[], &[]);
    check("gate1 CMO-limit", &r, &REF_M1_CMO);
}

#[test]
fn mesh_gate2_tdep_enthalpy_parity() {
    let th = thermo_tdep();
    let r = mesh_tower(&[0.4, 0.3, 0.3], 10.0, 12, 6, 4.0, 5.0, &th, 150e3,
                       None, &[1.0], &[], &[], &[], &[]);
    check("gate2 T-dependent enthalpy", &r, &REF_M2_TDEP);
}

#[test]
fn mesh_gate4_vapour_draw_parity() {
    let th = thermo_cmo();
    let r = mesh_tower(&[0.4, 0.3, 0.3], 10.0, 12, 6, 4.0, 5.0, &th, 150e3,
                       None, &[1.0], &[], &[(9, 1.0)], &[], &[]);
    check("gate4 vapour draw", &r, &REF_M4_VDRAW);
}

#[test]
fn mesh_gate5_pumparound_parity() {
    let th = thermo_cmo();
    let r = mesh_tower(&[0.4, 0.3, 0.3], 10.0, 12, 6, 4.0, 5.0, &th, 150e3,
                       None, &[1.0], &[], &[], &[(6, 9, 2.0, 20000.0)], &[]);
    check("gate5 pumparound", &r, &REF_M5_PA);
}

#[test]
fn mesh_gate3_binary_efficiency_parity() {
    let th = thermo_bin();
    let r1 = mesh_tower(&[0.5, 0.5], 10.0, 8, 4, 5.0, 5.0, &th, 101325.0,
                        None, &[1.0], &[], &[], &[], &[]);
    check("gate3 binary E=1", &r1, &REF_BIN_E1);
    let r07 = mesh_tower(&[0.5, 0.5], 10.0, 8, 4, 5.0, 5.0, &th, 101325.0,
                         None, &[0.7], &[], &[], &[], &[]);
    check("gate3 binary E=0.7", &r07, &REF_BIN_E07);
    // Directional gate of the Python battery, restated.
    assert!(r07.x_distillate[0] < r1.x_distillate[0] - 0.005,
            "E=0.7 xD {} vs E=1 xD {}", r07.x_distillate[0], r1.x_distillate[0]);
}
